set -e
ROOT=~/.cache/g255-a570; mkdir -p $ROOT; cd $ROOT
rm -rf red; git clone -q --depth 1 -b main https://github.com/hyper-light/slates.git red
cd red; git log --oneline -1 | cut -c1-60; uptime
echo '' | base64 -d > crates/server/src/pressure.rs
echo '' | base64 -d >> crates/server/src/nfs.rs
perl -pi -e 's/^mod retention;$/mod pressure;\nmod retention;/' crates/server/src/lib.rs
grep -c "^mod pressure" crates/server/src/lib.rs; grep -c "mod purge_round_tests" crates/server/src/nfs.rs
export CARGO_TARGET_DIR=$ROOT/target
cargo test -q -p slates-server --lib -- a_reported_fall_in_available_memory_is_held_back_without_a_tick a_refused_purge_goes_again_a_window_after_its_round --nocapture 2>&1 | grep -E "test result|held back|went again|panicked|FAILED|^error|warning: unused" | tail -12
